function debounce(fn, delay) {
  var timeoutId = null;
  return function () {
    var args = arguments;
    clearTimeout(timeoutId);
    timeoutId = setTimeout(function () {
      fn.apply(null, args);
    }, delay);
  };
}

var calls = 0;
var bump = debounce(function () { calls++; }, 5);
bump(); bump();
console.log("scheduled");

